// Code Node: JSON to Markdown Converter
const jsonResponse = $input.first().json.output || {};
const jsonQuestion = $('When chat message received').first().json.chatInput || {};

function convertJSONToMarkdown(jsonData, jsonQ) {
  let markdown = "";

  // Handle string input (parse if needed)
  let parsedData;
  if (typeof jsonData === 'string') {
    try {
      parsedData = JSON.parse(jsonData);
    } catch (error) {
      return jsonData; // Return as-is if not valid JSON
    }
  } else {
    parsedData = jsonData;
  }

  // Handle error responses
  if (parsedData.error) {
    return parsedData.error;
  }

  // Question
  if (jsonQ) {
    markdown += "## Question\n";
    markdown += jsonQ;
  }

  markdown += "\n";

  // AI Response
  markdown += "## AI Response\n";

  // 1. ANSWER FOR SALES Section
  if (parsedData.answer_for_sales) {
    markdown += "#### ANSWER FOR SALES\n";
    const sales = parsedData.answer_for_sales;

    if (sales.decision) {
      markdown += sales.decision + ".";
    }

    if (sales.action) {
      markdown += sales.action + "\n";
    }

    if (sales.risk_level) {
      markdown += `**Risk Level**: \`${sales.risk_level}\`\n`;
    }

    markdown += "\n";
  }

  // 2. RATIONALE Section
  if (parsedData.rationale) {
    markdown += "#### RATIONALE\n";
    const rationale = parsedData.rationale;

    let rationaleText = "";

    if (rationale.why_provision_exists) {
      rationaleText += rationale.why_provision_exists + " ";
    }

    if (rationale.impact_if_modified) {
      rationaleText += rationale.impact_if_modified + " ";
    }

    if (rationale.customer_explanation) {
      rationaleText += rationale.customer_explanation + " ";
    }

    if (rationale.escalation_trigger) {
      rationaleText += rationale.escalation_trigger;
    }

    markdown += rationaleText.trim() + "\n\n";
  }

  // 3. CITATIONS Section
  if (parsedData.citations && Array.isArray(parsedData.citations)) {
    markdown += "#### CITATIONS\n";

    parsedData.citations.forEach((citation, index) => {
      if (citation.document) {
        markdown += `**${citation.document}**\n`;

        let citationDetails = "- ";

        if (citation.page) {
          citationDetails += `Page ${citation.page}`;
        }

        if (citation.section) {
          if (citation.page) citationDetails += ", ";
          citationDetails += `Section ${citation.section}`;
        }

        if (citation.topic) {
          if (citation.page || citation.section) citationDetails += ", ";
          citationDetails += `Topic: ${citation.topic}`;
        }

        if (citation.quote) {
          citationDetails += `: *"${citation.quote}"*`;
        }

        markdown += citationDetails + "\n";

        if (index < parsedData.citations.length - 1) {
          markdown += "\n";
        }
      }
    });
  }

  return markdown.trim();
}

// Convert the JSON response to markdown
const markdownOutput = convertJSONToMarkdown(jsonResponse, jsonQuestion);

// Log for debugging
console.log("Converting JSON to Markdown...");
console.log("Input type:", typeof jsonResponse);
console.log("Output length:", markdownOutput.length);

// Return the markdown
return [{
  json: {
    markdown: markdownOutput,
    original_json: jsonResponse,
    conversion_successful: markdownOutput.length > 0
  }
}];

// Code Node: Flexible Contract Response Validation with Iteration Management
const rawResponse = $input.first().json.markdown || $input.first().json.output || "";
// Ensure response is always a string
const response = typeof rawResponse === 'string' ? rawResponse : String(rawResponse || "");
const originalQuestion = $('When chat message received').first().json.chatInput || "";
const previousIteration = $input.first().json.iteration || 0;
const currentIteration = previousIteration + 1;

function validateContractResponse(response, originalQuestion, iteration) {
  const failures = [];
  let score = 10;

  // Check if response is empty
  if (!response || response.trim().length === 0) {
    return {
      passed: false,
      score: 0,
      failures: [{
        issue: "Empty response",
        location: "Overall",
        fix: "Generate a complete response with all required sections"
      }],
      revision_needed: "Complete response required",
      timestamp: new Date().toISOString(),
      iteration: iteration,
      response: response,
      original_question: originalQuestion
    };
  }

  // 1. Check Required Sections - Very flexible patterns
  const sections = {
    'ANSWER FOR SALES': {
      found: false,
      content: "",
      patterns: [
        /answer\s*for\s*sales/i,
        /sales\s*answer/i,
        /answer\s*to\s*sales/i
      ]
    },
    'RATIONALE': {
      found: false,
      content: "",
      patterns: [
        /rationale/i,
        /reasoning/i,
        /explanation/i
      ]
    },
    'CITATIONS': {
      found: false,
      content: "",
      patterns: [
        /citations?/i,
        /references?/i,
        /sources?/i
      ]
    }
  };

  // Find sections with very flexible matching
  const responseUpper = response.toUpperCase();

  // Check for ANSWER FOR SALES section
  if (responseUpper.includes('ANSWER') && responseUpper.includes('SALES')) {
    sections['ANSWER FOR SALES'].found = true;
    // Extract content between this section and next section
    const startMatch = response.match(/answer\s*for\s*sales[:\s]*([\s\S]*?)(?=rationale|citations|$)/i);
    if (startMatch) {
      sections['ANSWER FOR SALES'].content = startMatch[1].trim();
    }
  }

  // Check for RATIONALE section
  if (responseUpper.includes('RATIONALE')) {
    sections['RATIONALE'].found = true;
    const rationaleMatch = response.match(/rationale[:\s]*([\s\S]*?)(?=citations|$)/i);
    if (rationaleMatch) {
      sections['RATIONALE'].content = rationaleMatch[1].trim();
    }
  }

  // Check for CITATIONS section
  if (responseUpper.includes('CITATION')) {
    sections['CITATIONS'].found = true;
    const citationsMatch = response.match(/citations?[:\s]*([\s\S]*?)$/i);
    if (citationsMatch) {
      sections['CITATIONS'].content = citationsMatch[1].trim();
    }
  }

  // Only fail if sections are completely missing
  for (const sectionName in sections) {
    if (!sections[sectionName].found) {
      failures.push({
        issue: `Missing section: ${sectionName}`,
        location: 'Structure',
        fix: `Add ${sectionName} section`
      });
      score -= 2;
    }
  }

  // 2. Validate ANSWER FOR SALES - Very general checks
  if (sections['ANSWER FOR SALES'].found && sections['ANSWER FOR SALES'].content) {
    const answerContent = sections['ANSWER FOR SALES'].content;

    // Just check if there's some mention of risk
    const hasRiskIndication = /(low|medium|high|minimal|significant|major)/i.test(answerContent);

    if (!hasRiskIndication) {
      failures.push({
        issue: 'No risk assessment mentioned',
        location: 'ANSWER FOR SALES',
        fix: 'Include risk level (Low/Medium/High or similar)'
      });
      score -= 0.5;
    }

    // Check if there's any directive (very flexible)
    const hasAnyDirective = answerContent.length > 20; // Just needs some content

    if (!hasAnyDirective) {
      failures.push({
        issue: 'Answer too brief',
        location: 'ANSWER FOR SALES',
        fix: 'Provide more detail in the answer'
      });
      score -= 1;
    }

    // Very generous length check
    const wordCount = answerContent.split(/\s+/).filter(w => w.length > 0).length;
    if (wordCount > 150) {
      failures.push({
        issue: `Answer might be too long (${wordCount} words)`,
        location: 'ANSWER FOR SALES',
        fix: 'Consider making answer more concise'
      });
      score -= 0.25;
    }
  }

  // 3. Validate RATIONALE - General checks
  if (sections['RATIONALE'].found && sections['RATIONALE'].content) {
    const rationaleContent = sections['RATIONALE'].content;

    // Just check it's not too long or too short
    const sentences = rationaleContent.split(/[.!?]+/).filter(s => s.trim().length > 5);

    if (sentences.length > 6) {
      failures.push({
        issue: `Rationale might be lengthy (${sentences.length} sentences)`,
        location: 'RATIONALE',
        fix: 'Consider keeping to 4-5 sentences'
      });
      score -= 0.5;
    }

    if (rationaleContent.length < 30) {
      failures.push({
        issue: 'Rationale too brief',
        location: 'RATIONALE',
        fix: 'Add more explanation'
      });
      score -= 1;
    }
  }

  // 4. Validate CITATIONS - Very flexible
  if (sections['CITATIONS'].found && sections['CITATIONS'].content) {
    const citationsContent = sections['CITATIONS'].content;

    // Look for any kind of list items (-, *, •, numbers, etc.)
    const lines = citationsContent.split('\n').filter(line => line.trim().length > 0);
    const citationLines = lines.filter(line => {
      const trimmed = line.trim();
      return trimmed.match(/^[-*•\d]/); // Starts with any list marker
    });

    if (citationLines.length === 0 && lines.length > 0) {
      // Maybe citations are just in paragraph form, that's okay
      citationLines.push(...lines);
    }

    if (citationLines.length === 0) {
      failures.push({
        issue: 'No citations found',
        location: 'CITATIONS',
        fix: 'Add at least one citation or reference'
      });
      score -= 2;
    } else {
      // For each citation, just check for basic elements
      citationLines.forEach((line, idx) => {
        const lineNum = idx + 1;

        // Very flexible checks
        const hasDocReference = /\.(pdf|doc|docx|txt)|document|agreement|contract|master/i.test(line);
        const hasLocation = /page|section|clause|article|paragraph|p\.|§/i.test(line);
        // Better quote detection - more flexible patterns
        const hasQuote = (
          /"[^"]*"/g.test(line) ||           // Straight double quotes
          /'[^']*'/g.test(line) ||           // Straight single quotes  
          /"[^"]*"/g.test(line) ||           // Curly double quotes
          /'[^']*'/g.test(line) ||           // Curly single quotes
          /\*"[^"]*"\*/g.test(line) ||       // Quotes in italic markdown
          line.includes('"') && line.includes('"') // Any opening and closing quotes
        );

        console.log(`Line: ${line}`);
        console.log(`Has quote: ${hasQuote}`);

        if (!hasQuote && line.length < 20) {
          // Only suggest quotes if the citation is very short
          failures.push({
            issue: `Citation ${lineNum} might benefit from a quote`,
            location: 'CITATIONS',
            fix: 'Consider adding a relevant quote if applicable'
          });
          score -= 0.1;
        }
      });
    }
  }

  // 5. Check for "not found" response - keep this strict
  if (response.includes("cannot find") || response.includes("not found")) {
    if (response.includes("contract") || response.includes("document")) {
      // It's a valid "not found" response
      return {
        passed: true,
        score: 10,
        failures: [],
        revision_needed: null,
        timestamp: new Date().toISOString(),
        iteration: iteration,
        original_question: originalQuestion,
        response: response,
        summary: "Valid 'not found' response"
      };
    }
  }

  // Calculate final score - be more lenient
  // score = Math.max(0, Math.min(10, score));

  // More lenient passing criteria
  const passed = score >= 9.5 && failures.filter(f => !f.issue.includes('might')).length === 0;

  // Check if max iterations reached
  const maxIterations = 3;
  if (!passed && iteration >= maxIterations) {
    return {
      passed: false,
      score: score,
      failures: failures,
      revision_needed: "MAX ITERATIONS REACHED - Proceeding to human review",
      timestamp: new Date().toISOString(),
      iteration: iteration,
      original_question: originalQuestion,
      response: response,
      summary: `Max iterations (${maxIterations}) reached`,
      force_proceed: true
    };
  }

  return {
    passed: passed,
    score: score,
    failures: failures,
    revision_needed: passed ? null : "Minor improvements suggested",
    timestamp: new Date().toISOString(),
    iteration: iteration,
    original_question: originalQuestion,
    response: response,
    summary: passed ? "Response acceptable" : `${failures.length} suggestions (iteration ${iteration}/${maxIterations})`,
    force_proceed: false
  };
}

// Execute validation with iteration tracking
const result = validateContractResponse(response, originalQuestion, currentIteration);

// Log for debugging
console.log(`Validation iteration ${currentIteration}: Score ${result.score}/10`);
console.log(`Response type: ${typeof response}, Length: ${response.length}`);

// Return result for n8n
return [{
  json: {
    ...result,
    next_iteration: currentIteration + 1
  }
}];

