          citationDetails += `Topic: ${citation.topic}`;
        }

        if (citation.quote) {
          citationDetails += `: *"${citation.quote}"*`;
        }

        markdown += citationDetails + "\n";

        if (index < parsedData.citations.length - 1) {
          markdown += "\n";
        }
      }
    });
  }

  return markdown.trim();
}

